-- создание таблицы График Дней открытых дверей (День открытых дверей) 
create table open_door_time
(
	id serial primary key,
	even_date Date not null,
	event_time Time not null default '13:00'

);

------------------------------------------------------------
-- Шаг 1.
-- Подключиться к БД postgresq
-- jdbc:postgresql://localhost:5432/postgres
-- пароль 200202
------------------------------------------------------------


--заполнение таблицы График Дней открытых дверей (День открытых дверей) 
insert into open_door_time(even_date) values
('2026-01-31'),
('2026-02-28'),
('2026-03-28'),
('2026-04-25'),
('2026-05-30');

select even_date, event_time
 from open_door_time dt
 --where dt.even_date >= CURRENT_DATE -- TODO
order by even_date, event_time
 --limit 0
;


/*
