------------------------------------------------------------
-- Шаг 2.
-- Функция выводит в консоль Просто все дни открытых дверей
------------------------------------------------------------

select even_date, event_time
  from OPEN_DOOR_TIME dt
 where 1=1
--   and dt.even_date >= :day_param -- Первый день этого года
 order by even_date, event_time
;

