--drop table filling_in_data_for_specializations;
--delete from filling_in_data_for_specializations;

-- создание таблицы для информации всех специальностей 
CREATE TABLE filling_in_data_for_specializations 
(
 	id serial primary key,
    specialty_id INT REFERENCES specialties_list(id), 
    content_type text,
    content  TEXT NOT null
);


select t.id, t.specialty_id 
	  ,sp.title  as specialty_nm
	  ,sp.cod    as specialty_code
	  ,t.content_type
	  ,ct.content_type as title
--      ,case 
--          when t.content_type = 10 then 'Квалификация'
--          when t.content_type = 20 then 'Краткое описание специальности'
--          when t.content_type = 30 then 'Область профессиональной деятельности'
--          when t.content_type = 40 then 'Где работает'
--          when t.content_type = 50 then 'Средства труда'
--          when t.content_type = 60 then 'Основные виды деятельности'
--          when t.content_type = 70 then 'Какими качествами должен обладать'
--          when t.content_type = 80 then 'Должности в организациях'
--          else t.content_type::text
--       end as title
	  ,t."content" as body
	  ,t.*
  from FILLING_IN_DATA_FOR_SPECIALIZATIONS t -- Разделы для карточки специальностей
  left join TYPE_CONTENT ct -- Тип контента
    on ct.id = t.content_type
  left join SPECIALTIES_LIST sp
    on sp.id = t.specialty_id 
 where 1=1
   and t.specialty_id = :specialty_id
 order by t.specialty_id, t.content_type, t.id
;


            SELECT t.id
                ,t.specialty_id 
                ,sp.title AS specialty_nm
                ,sp.cod AS specialty_code
                ,t.content_type
                ,CASE 
                    WHEN t.content_type = 10 THEN 'Не указана' -- 'Квалификация'
                    WHEN t.content_type = 20 THEN 'Не указано' -- 'Краткое описание специальности'
                    WHEN t.content_type = 30 THEN 'Не указана' -- 'Область профессиональной деятельности'
                    WHEN t.content_type = 40 THEN 'Не указано' -- 'Где работает'
                    WHEN t.content_type = 50 THEN 'Не указаны' -- 'Средства труда'
                    WHEN t.content_type = 60 THEN 'Не указаны' -- 'Основные виды деятельности'
                    WHEN t.content_type = 70 THEN 'Не указано' -- 'Какими качествами должен обладать'
                    WHEN t.content_type = 80 THEN 'Не указаны' -- 'Должности в организациях'
                    ELSE 'Не указано' 
                END AS body_empty
                ,ct.content_type AS title
                ,t.content AS body
            FROM FILLING_IN_DATA_FOR_SPECIALIZATIONS t
            LEFT JOIN TYPE_CONTENT ct ON ct.id = t.content_type
            LEFT JOIN SPECIALTIES_LIST sp ON sp.id = t.specialty_id 
            WHERE t.specialty_id = :specialty_id
            ORDER BY t.specialty_id, t.content_type, t.id;
            
select t.id
	  ,t.specialty_id 
	  ,sp.title  		as specialty_nm   -- Специальность
	  ,sp.cod    		as specialty_code -- Код специальности
	  ,t.content_type
	  ,ct.content_type  as title -- Наименование раздела карточки
	  ,t.content 		as body  -- Содержимое раздела
  from FILLING_IN_DATA_FOR_SPECIALIZATIONS t -- Контент для карточки специальностей
  left join TYPE_CONTENT ct -- Тип контента
    on ct.id = t.content_type
  left join SPECIALTIES_LIST sp -- Специальности
    on sp.id = t.specialty_id 
 where 1=1
   and t.specialty_id = :specialty_id
 order by t.specialty_id, t.content_type, t.id
;


select t.*
  from FILLING_IN_DATA_FOR_SPECIALIZATIONS t
 where 1=1
   and t.specialty_id = :specialty_id
 order by t.specialty_id, t.content_type, t.id
;

