-- создание таблицы Часто задаваемые вопросы
CREATE TABLE Admission_FAQ 
(
    id SERIAL PRIMARY KEY,
    admission_id INT REFERENCES Admission_Info(id) ON DELETE CASCADE, -- Связь с таблицей верхнего текста
    question TEXT, -- Сам текст вопроса 
    answer TEXT,   -- Текст ответа
    display_order INT    -- Порядок сортировки
);

-- заполнение таблицы часто задоваемые вопросы 
INSERT INTO Admission_FAQ (admission_id, question, answer, display_order) VALUES 
(1, 'ЧАСТО ЗАДАВАЕМЫЕ ВОПРОСЫ:', NULL, 0),
(1, 'Можно ли поступить с 2 ОГЭ?', 'В рамках Федерального закона от 01.04.2025 г. №40-ФЗ «О проведении эксперимента по расширению доступности среднего профессионального образования» Колледж туризма и прикладных технологий Санкт-Петербурга ведет прием на обучение по профессии "Повар, кондитер".', 1),
(1, 'Есть ли при Колледже общежитие?', 'Общежития нет. В соответствии с законодательством граждане обязаны регистрироваться по месту временного пребывания.', 2),
(1, 'По какому адресу можно подавать документы?', 'Приемная комиссия находится по адресу: ст. метро Нарвская, наб. Обводного канала, д. 154-а. [Режим работы приемной комиссии](https://www.ktgs.ru/inspection/rejim_raboti_pk.php)', 3),
(1, 'Что нужно для подачи документов?', 'Все этапы подачи и перечень документов подробно указаны в документе [Перечень документов для поступления](https://www.ktgs.ru/upload/1site/priem/perechen_priem2025-2026.pdf)', 4),
(1, 'Обязательно ли присутствие родителя/законного представителя при подаче документов?', 'Если Вам нет 18 лет, то заявление на зачисление и согласие на обработку персональных данных несовершеннолетнего подписывает родитель/законный представитель. Прием документов на договорную форму обучения осуществляется только в присутствии законного представителя несовершеннолетнего.', 5),
(1, 'По каким специальностям осуществляется прием?', '[Перечень специальностей на 2025 - 2026 уч. год](https://www.ktgs.ru/upload/2025/perechen-specialnostej-na-2025-2026-upd-24-02-2025.pdf)', 6),
(1, 'Есть ли бюджетные места для обучения?', 'Количество бюджетных мест указано в документе [План приема на 2025-2026 уч.г.](https://www.ktgs.ru/upload/2025/plan-priyoma-na-2025-2026-uch-god-byudzhet-upd-24-02-2025.pdf)', 7),
(1, 'Можно ли поступить в ваш колледж на базе 8 классов?', 'Прием в колледже осуществляется только на базе 9 или 11 классов.', 8),
(1, 'Какие документы необходимы при подаче заявления?', 'Все этапы подачи и перечень документов подробно указаны в документе [Перечень документов для поступления](https://www.ktgs.ru/upload/1site/priem/perechen_priem2025-2026.pdf)', 9),
(1, 'Нужно ли заверять копии документов у нотариуса?', 'Копии документов заверять не нужно, если в Приемной комиссии Вы предъявите лично оригинал документа об образовании. В этом случае сотрудник Приемной комиссии заверяет копию самостоятельно. Без предъявления оригинала незаверенная копия документа об образовании не будет принята к рассмотрению. При отсутствии оригинала аттестата при подаче документов предоставляется нотариально заверенная копия документа об образовании.Напоминаем, что зачисление возможно только при наличии оригинала документа об образовании.', 10),
(1, 'Могут ли подать/забрать документы вместо абитуриента его родственники/знакомые?', 'Подать/забрать документы за Вас могут ваши родственники или друзья только при наличии у них паспорта, расписки и нотариальной доверенности', 11),
(1, 'Каким способом можно подать документы в Ваш Колледж?', 'Порядок подачи документов подробно прописан в [Правилах приема на 2025-2026 уч.год, пункт 4.8](https://www.ktgs.ru/upload/2025/pravila-priyoma-2025-2026-upd-06-03-2025.pdf)', 12),
(1, 'Можно ли подать заявление на несколько специальностей?', 'Заявление о зачислении подается на одну специальность/профессию.', 13),
(1, 'Какие экзамены/ЕГЭ/ОГЭ необходимы для поступления?', '• Прием по всем специальностям в нашем колледже осуществляется без экзаменов, без учета ЕГЭ/ОГЭ. Учитывается только средний балл аттестата [Вступительные испытания](https://www.ktgs.ru/inspection/trainings.php)', 14),
(1, 'Как считается средний балл?', 'Средний балл аттестата/диплома представляет собой сумму оценок по предметам общеобразовательного цикла из приложения к аттестату/диплому, разделенную на количество дисциплин', 15),
(1, 'Каким должен быть средний балл для зачисления?', 'Проходной балл зависит от количества поданных документов и среднего балла этих документов. Предсказать его никто не может.В соответствии со средним баллом аттестата абитуриенты распределяются по рейтингу (по списку от высшего среднего балла - к низшему). Рейтинговые списки публикуются на сайте в течение всего приема документов. После окончания приема к зачислению представляются абитуриенты, прошедшие по конкурсу и представившие оригинал документа об образовании.', 16),
(1, 'Есть ли льготы при поступлении?', 'Поступающий представляет оригинал документа об образовании и (или) документа об образовании и о квалификации, а также документа, подтверждающего право преимущественного или первоочередного приема в соответствии с частью 4 статьи 68 Федерального закона "Об образовании в Российской Федерации" (при наличии), в сроки, установленные образовательной организацией.', 17),
(1, 'Предоставляется ли отсрочка от службы в армии?', 'В соответствии с законом «О воинской обязанности и военной службе» от 28.03.1998г. №53-ФЗ право на отсрочку от призыва на военную службу имеют граждане: обучающиеся по очной форме обучения в образовательных организациях по имеющим государственную аккредитацию образовательным программам среднего профессионального образования, - в период освоения указанных образовательных программ, но не свыше сроков получения среднего профессионального образования, установленных федеральными государственными образовательными стандартами (статья 24, п. 2, а, пп 2).', 18),
(1, 'Можно ли подать документы иногородним гражданам, не имеющим временной регистрации по месту пребывания', 'Отсутствие регистрация в Санкт-Петербурге или Ленинградской области для граждан РФ не является препятствием для подачи документов на обучение. Но необходимо знать, что в соответствии с законодательством граждане Российской Федерации могут пребывать без регистрации по месту пребывания на территории Российской Федерации не более 90 дней. Документы, регламентирующие права, обязанности и ответственность граждан по регистрационному учету: 1. Правила Регистрации и снятия граждан Российской Федерации с регистрационного учета по месту пребывания и по месту жительства в пределах Российской Федерации, п. 9. 2. Приказ Министерства внутренних дел Российской Федерации от 31 декабря 2017 г. N 984 3. Кодекс Административных Правонарушений РФ часть 2 ст. 19.15.1., 19.15.2', 19),
(1, 'На каких условиях могут поступить иностранные граждане?', '[Прием иностранных граждан](https://www.ktgs.ru/inspection/foreigners_pk.php)', 20),
(1, 'В каком учебном корпусе будет проходить обучение?', 'Обучающиеся 1 курса, поступившие на базе 9 классов, проходят программу среднего общего образования (10-11 кл.) на [Отделении общеобразовательная подготовки](https://www.ktgs.ru/OtdeleniaKolledzha/departments/general2/) (ст. м. Озерки, пр. Луначарского, д. 66). По окончании освоения программы, обучающиеся переходят на отделение, соответствующее выбранной специальности/профессии.
Обучающиеся, поступившие на базе 11-ти классов, обучаются на соответствующих отделениях с 1 курса.
[Отделение туризма и прикладных технологий](https://www.ktgs.ru/OtdeleniaKolledzha/departments/tour/) (ст. м. Петроградская, наб. реки Карповки, д. 11-а):
- Туризм и гостеприимство (направление «Предоставление туроператорских, турагентских и экскурсионных услуг»)
- Операционная деятельность в логистике
- Информационные системы и программирование
[Отделение гостиничного сервиса](https://www.ktgs.ru/OtdeleniaKolledzha/departments/gostservis/) (ст. м. Удельная, пр. Энгельса, д. 42):
- Туризм и гостеприимство (направление «Предоставление гостиничных услуг»)
[Отделение ресторанного сервиса](https://www.ktgs.ru/OtdeleniaKolledzha/departments/restoranservis/) (ст. м. Нарвская, наб. Обводного кан., д. 154-а):
- Поварское и кондитерское дело/ Повар, кондитер
- Официант, бармен
- Туризм и гостеприимство (направление «Предоставление услуг предприятий питания»)
[Отделение прикладных программ и цифровых технологий](https://www.ktgs.ru/OtdeleniaKolledzha/departments/commerce/) (ст. м. Озерки, пр. Луначарского, д. 66):
- Строительство и эксплуатация зданий и сооружений
- Торговое дело
- Прикладная геодезия
- Картография
- Информационные системы и программирование
- Сетевое и системное администрирование', 21),
(1, 'Если я хочу поступить (перевестись) на второй курс из другого колледжа, что для этого нужно сделать?', '[Перевод из другого учебного заведения](https://www.ktgs.ru/inspection/change_pk.php)', 22),
(1, 'На какой курс ВУЗа может поступить выпускник колледжа?', 'Прием на обучение по программам бакалавриата и программам специалитета лиц, имеющих среднее профессиональное образование, проводится как по результатам ЕГЭ, так и по результатам вступительных испытаний, форма и перечень которых определяются образовательной организацией высшего образования (ст. 70, п. 6 ФЗ «Об образовании»). При зачислении в ВУЗ на направление подготовки бакалавриата соответствующего профиля, срок обучения может быть сокращен за счет перезачета дисциплин, изученных в колледже. Решение об ускоренном обучении обучающегося принимается организацией на основании его личного заявления.', 23),
(1, 'Ваш Колледж сотрудничает с каким-нибудь ВУЗом?', '[Сотрудничество с ВУЗами](https://www.ktgs.ru/inspection/university_pk.php)', 24),
(1, 'Как поступить на обучение на коммерческую (платную) основу, если не поступил на бюджет?', 'Зачисление граждан в Колледж для обучения по договорам с оплатой стоимости обучения осуществляется в рамках предельной численности контингента, установленной лицензией на право ведения образовательной деятельности. Граждане, поступающие на места по договорам с оплатой стоимости обучения, зачисляются в Колледж только после заключения договора и внесения оплаты в соответствии с условиями договора.', 25),
(1, 'Где можно ознакомиться с Уставом, лицензией, аккредитацией и другими локальными актами?', '[Общие документы: Устав, лицензия, аккредитация](https://www.ktgs.ru/about/Documenty/docs/obschie-dokumenty.php) и [Общие документы Локальные акты](https://www.ktgs.ru/about/Documenty/docs/lokalnye-akty.php)', 26),
(1, 'Какие предметы я буду изучать?', '[Образовательные стандарты и требования](https://www.ktgs.ru/about/ObrazovatelnyeStandarty/); [Учебные планы](https://www.ktgs.ru/study/study_work/uchplan.php)', 27);


