insert into information_stat(specialty_id, title,content) values 
(1,'Прием иностранных граждан','Приём иностранных граждан в Колледж туризма и прикладных технологий Санкт-Петербурга осуществляется на основании действующих Правил приёма в Колледж туризма и прикладных технологий Санкт-Петербурга и Федерального закона от 24 мая 1999 № 99-ФЗ «О государственной политике Российской Федерации в отношении соотечественников за рубежом».

Документы, необходимые для иностранных граждан


Документ об образовании (аттестат за 9 или 11 класс, диплом об окончании техникума (училища, колледжа), вуза)
Нотариально заверенная ксерокопия документа об образовании при необходимости со свидетельством его эквивалентности и с переводом на русский язык.
Ксерокопия паспорта (все страницы)
Ксерокопия нотариально заверенного перевода паспорта (все страницы).
Копия документа, подтверждающую регистрацию иностранного гражданина на территории Санкт-Петербурга или Ленинградской области.
Цветные фотографии (3*4 см) 4 шт. без уголка
Ксерокопия СНИЛС
Медицинские документы (предоставляются при зачислении до 25.08.2025):
справка ф-086-у за текущий год (включая отметку стоматолога, окулиста и лор-врача, а также клинические анализы крови и мочи)
ксерокопия сертификата о прививках
справка от нарколога; справки из туберкулезного, психоневрологического и кожно-венерологического диспансеров
ксерокопия медицинского страхового полиса (с двух сторон)
данные о ФЛГ (флюорографии) обследовании за текущий год
результат лабораторного исследования материала на COVID-19 методом полимеразной цепной реакции (ПЦР), отобранного не позднее 72 часов
Документы подтверждающих прохождение медицинского освидетельствования, обязательной государственной дактилоскопической регистрации и фотографирования.'),

(1,'Сотрудничество с ВУЗами','В нашем Колледже с 1994 года успешно реализуется программа непрерывного образования по системе: Колледж – ВУЗ. Абитуриенты с соответствующим набором ЕГЭ, прошедшие по конкурсу аттестатов учатся в Колледже бесплатно и могут поступить на параллельное обучение по профильной специальности (заочно) в Санкт-Петербургский институт гостеприимства (СПИГ). Направление обучения в ВУЗе зависит от набора соответствующих предметов ЕГЭ.

По окончании обучения в Колледже остаток срока обучения в ВУЗе составляет 2-3 года с сохранением скидок по оплате за обучение. Преимущества параллельного обучения – за 5 лет место работы и два образования.');



