-- создание таблицы для Образовательного кредита 
CREATE TABLE Education_Loan_Content 
(
    id SERIAL PRIMARY KEY,
    specialty_id INT REFERENCES specialties_list(id),
    content TEXT NOT NULL
);


--заполнение таблицы для образовательного кредита
INSERT INTO Education_Loan_Content (content) VALUES (
'В нашей стремительно меняющейся экономике среднее профессиональное образование открывает перед молодыми людьми двери в мир высокооплачиваемого и квалифицированного труда. При этом с каждым годом колледжи и техникумы все более востребованы у абитуриентов. Но что делать, если бюджетного места не хватило, а финансовые обстоятельства становятся препятствием на пути к получению желаемого образования? Решением этой проблемы может стать использование образовательного кредита с государственной поддержкой.

Подробную информацию об условиях программы вы можете изучить в специальном пособии, а также в разделе [«Вопросы и ответы»](https://open.edu.gov.ru/faq/#type=73) на сайте Минпросвещения России.

**Условия предоставления**
Образовательный кредит может получить любой гражданин Российской Федерации. При этом, потенциальному заемщику должно быть не меньше 14 лет. Чтобы воспользоваться государственной поддержкой необходимо:

1. Подписать договор на платное обучение с колледжем;
2. Прийти с паспортом, договором и счетом на оплату в офис банков-партнеров (ПАО Сбербанк или РНКБ Банк);
3. Ознакомиться с условиями кредита и подпиисать договор;
4. Получить подтверждение от учебного заведения. Пошаговая инструкция в [чек-листе](https://vk.com/doc-224704750_675251199).

**Материалы для студентов и абитуриентов**
* Образовательное кредитование: [пособие для студентов СПО](https://vk.com/doc-224704750_675216781);
* [Чек-лист](https://vk.com/doc-224704750_675251199) о получении кредита на образование по программе СПО с господдержкой.'
);


